			return cmp.Compare(aNum, bNum)
		}
		return strings.Compare(aParts[i], bParts[i])
	}
	return cmp.Compare(len(aParts), len(bParts))
}

func sortVersions(versions []string) []string {
	slices.SortFunc(versions, compareVersions)
	return versions
