		{"1.0.1", "2026-10-01T09:00:00Z"},
		{"1.0.2", "2026-10-01T09:00:00Z"},
		{"1.0.3", "2026-10-01T09:00:00Z"},
		{"1.0.4", "2026-10-01T10:00:00Z"},
	}
	for _, item := range ordered {
