	}
	for i := range want {
		if collected[i] != want[i] {
			t.Fatalf("collected %v, want %v (newest first, id tie-break)", collected, want)
		}
	}
	if pages != 3 {
		t.Fatalf("pages = %d, want 3 (2+2+1)", pages)
	}
}

